+                args += p.repeat(arg_rule, /* min = */ is_required ? 1 : 0, /* max = */ 1);
+            });
+
+            auto tool_open = p.tool_open(
+                p.literal(FUNCTION_START) +
+                p.tool_name(p.literal(name)) +
+                p.literal(">") +
+                p.optional(p.literal("\n")));
+            auto tool_close = p.tool_close(
+                p.optional(p.literal("\n")) +
+                p.literal(FUNCTION_END) +
+                p.optional(p.literal("\n")));
