+            auto tool_parser = p.tool(tool_open + p.tool_args(args) + tool_close);
+            tool_choice |= p.rule("tool-" + name, tool_parser);
+        });
+
+        auto min_calls = inputs.tool_choice == COMMON_CHAT_TOOL_CHOICE_REQUIRED ? 1 : 0;
+        auto max_calls = inputs.parallel_tool_calls ? -1 : 1;
+        auto tool_call = p.rule("tool-call",
+            p.literal(TOOL_CALL_START) +
+            p.optional(p.literal("\n")) +
+            tool_choice +
+            p.literal(TOOL_CALL_END) +
+            p.space());
+        auto tool_calls = p.trigger_rule("tool-call-root", p.repeat(tool_call, min_calls, max_calls));
+
+        auto content_before_tools = p.content(p.until(TOOL_CALL_START));
+        return generation_prompt + reasoning + content_before_tools + tool_calls + end;
+    });
