+    // Cache-identity for the frames of THIS video. Image bitmaps get a sha256
+    // of their bytes ("use sha256 to prevent cache poisoning" above); video
+    // frames got NO id at all, so in the server's prompt-cache comparison
+    // (server-common.cpp, id_ai == id_bi) two frames from two DIFFERENT videos
+    // compared as "" == "" and matched. Send two videos with the same prompt
+    // text and the second reuses the first's decoded media wholesale — a
+    // reproducible wrong-video description (8/8 with identical text, 0/8 with
+    // the ids in place). One hash of the source per video, plus a frame index.
+    std::string source_id;
+    int32_t frame_counter = 0;

     // RAII wrapper for managing subprocess
     struct subprocess_handle {
@@ -788,6 +798,10 @@ struct mtmd_helper_video {
         current_frame++;
         mtmd_bitmap * frame = mtmd_bitmap_init(info.width, info.height, frame_buf.data());
         mtmd_bitmap_set_mergeable(frame, true);
+        if (!source_id.empty()) {
+            std::string fid = source_id + "#" + std::to_string(frame_counter++);
+            mtmd_bitmap_set_id(frame, fid.c_str());
+        }
